# -*- coding: utf-8 -*-
import json, unicodedata, re

def slugify(text):
    text = unicodedata.normalize('NFD', text).encode('ascii', 'ignore').decode('utf-8')
    text = re.sub(r'[^a-zA-Z0-9]+', '_', text).strip('_').lower()
    return text

