# Summary and duplicate checks:
categories = {
    'animaux': ANIMAUX,
    'aliments': ALIMENTS,
    'objets': OBJETS,
    'nature': NATURE,
    'transports': TRANSPORTS
}

all_words = []
used_ids = set()

for cat_name, word_list in categories.items():
    print(f"Checking category: {cat_name} (initial count: {len(word_list)})")
    cat_words = []
    cat_seen = set()
    for item in word_list:
        word, level, emoji, hint, example, color = item
        clean_word = word.strip().lower()
        if clean_word in cat_seen:
            continue
        cat_seen.add(clean_word)

        # ID: slugify
        base_id = slugify(clean_word)
        word_id = base_id
        idx = 2
        while word_id in used_ids:
            word_id = f"{base_id}_{idx}"
            idx += 1
        used_ids.add(word_id)

        obj = {
            "id": word_id,
            "word": word.strip(),
            "level": level,
            "category": cat_name,
            "emoji": emoji,
            "hint": hint,
            "example": example,
            "color": color
        }
        cat_words.append(obj)
        all_words.append(obj)
    print(f" -> Unique in {cat_name}: {len(cat_words)}")

print(f"\nTotal words generated: {len(all_words)}")
